/* ============================================================
   REAL product detail data from applegadgetsbd.com
   Source: storeapi.applegadgetsbd.com/api/product/{slug}
   Contains the live site's exact Specification table, Description (rich text),
   SEO copy, photo gallery and per-variant pricing (Colour / Storage based).
   ============================================================ */

export interface VariantOption {
  label: string;
  value: string;
}

/** one purchasable combination, e.g. Black + 12/256GB → ৳113,999 */
export interface Variant {
  sku?: string;
  price: number;
  oldPrice?: number;
  stock: number;
  status: string;
  /** option name → value, e.g. { Color: "Black", Storage: "12/256GB" } */
  options: Record<string, string>;
  color?: string;
  colorCode?: string;
  img?: string;
}

export interface SpecGroup {
  name: string;
  /** "|" separated rows from the live site, already split for display */
  rows: { label: string; value: string }[];
}

export interface ProductDetail {
  slug: string;
  brand?: string;
  collections: string[];
  media: string[];
  specs: SpecGroup[];
  /** plain-text description blocks (headings kept) */
  description: string;
  /** short SEO paragraph used under "Description" */
  seoDescription?: string;
  variants: Variant[];
  cashType?: string;
}

const toRows = (details: string): { label: string; value: string }[] =>
  details
    .split("|")
    .map((r) => r.trim())
    .filter(Boolean)
    .map((r) => {
      const i = r.indexOf(":");
      return i > 0 && i < 42 ? { label: r.slice(0, i).trim(), value: r.slice(i + 1).trim() } : { label: "", value: r };
    });

